{
	ucl_object_t *nobj;

	if (len > 0 && begin != NULL) {
		nobj = ucl_object_fromstring_common(begin, len, 0);

		if (parser->last_comment) {
			/* We need to append data to an existing object */
			DL_APPEND(parser->last_comment, nobj);
		}
		else {
			parser->last_comment = nobj;
		}
	}
}

